def get_service_type():

    valid_types = {"A", "B", "C", "D", "E"}

    while True:
        print("\n  Type of service:")
        print("    A - General service")
        print("    B - Priority")
        print("    C - Documents")
        print("    D - Pick up documents")
        print("    E - Other subjects")

        option = input("\n  * Select service type: ").strip().upper()

        if option in valid_types:
            return option

        print("  Invalid option. Please choose A, B, C, D, or E.\n")
        
def get_input(expected_type, text):
    while True:
        try:
            value = input(text)

            if expected_type == str:
                value = value.strip()
                if value == "":
                    raise ValueError("Empty string not allowed")
                return value

            return expected_type(value)

        except ValueError:
            print(f"Invalid input. Please enter a valid {expected_type.__name__}.")
